const icon_t *theme_preview_icon(int theme) {
    return theme == 1 ? &theme_1_icon_fish : theme == 2 ? &theme_2_icon_fish : theme == 3 ? &theme_3_icon_fish : 0;
}

const uint8_t *theme_font_glyph(int theme, int scale, unsigned char ch) {
    if (ch < 32 || ch > 126) return 0;

    if (theme == 1 && scale == 2) return font_1_2 + (ch - 32) * 70;

    if (theme == 1 && scale == 3) return font_1_3 + (ch - 32) * 158;

    if (theme == 2 && scale == 2) return font_2_2 + (ch - 32) * 70;

    if (theme == 2 && scale == 3) return font_2_3 + (ch - 32) * 158;

    return 0;
}
